import{_ as l,a0 as r,w as o,s as p,I as a,a1 as e,A as i,x as s,ao as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const m=JSON.parse('{"title":"如何在 Ubuntu 中修复 VirtualBox 的 “Kernel driver not installed (rc=-1908)” 错误 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 中修复 VirtualBox 的 “Kernel driver not installed (rc=-1908)” 错误 | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 中修复 VirtualBox 的 “Kernel driver not installed (rc=-1908)” 错误 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 中修复 VirtualBox 的 “Kernel driver not installed (rc=-1908)” 错误 | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190815 How To Fix -Kernel driver not installed (rc--1908)- VirtualBox Error In Ubuntu","title":"如何在 Ubuntu 中修复 VirtualBox 的 “Kernel driver not installed (rc=-1908)” 错误","tag":"201908","desc":""},"relativePath":"201908/20190815 How To Fix -Kernel driver not installed (rc--1908)- VirtualBox Error In Ubuntu.md","filePath":"[post].md"}'),d={name:"201908/20190815 How To Fix -Kernel driver not installed (rc--1908)- VirtualBox Error In Ubuntu.md"};function h(b,n,x,g,k,v){const t=r("Link");return o(),p("div",null,[a("p",null,[e(t,{href:"collector:",title:"lujun9972"},{default:i(()=>[...n[0]||(n[0]=[s("#",-1)])]),_:1}),n[5]||(n[5]=s(": subject: (How To Fix “Kernel driver not installed (rc=-1908)” VirtualBox Error In Ubuntu) ",-1)),e(t,{href:"collector:",title:"lujun9972"},{default:i(()=>[...n[1]||(n[1]=[s("#",-1)])]),_:1}),n[6]||(n[6]=s(": via: (",-1)),e(t,{href:"https://www.ostechnix.com/how-to-fix-kernel-driver-not-installed-rc-1908-virtualbox-error-in-ubuntu/"},{default:i(()=>[...n[2]||(n[2]=[s("https://www.ostechnix.com/how-to-fix-kernel-driver-not-installed-rc-1908-virtualbox-error-in-ubuntu/",-1)])]),_:1}),n[7]||(n[7]=s(") ",-1)),e(t,{href:"collector:",title:"lujun9972"},{default:i(()=>[...n[3]||(n[3]=[s("#",-1)])]),_:1}),n[8]||(n[8]=s(": author: (sk ",-1)),e(t,{href:"https://www.ostechnix.com/author/sk/"},{default:i(()=>[...n[4]||(n[4]=[s("https://www.ostechnix.com/author/sk/",-1)])]),_:1}),n[9]||(n[9]=s(")",-1))]),n[25]||(n[25]=u(`<h1 id="如何在-ubuntu-中修复-virtualbox-的-kernel-driver-not-installed-rc-1908-错误" tabindex="-1">如何在 Ubuntu 中修复 VirtualBox 的 “Kernel driver not installed (rc=-1908)” 错误 <a class="header-anchor" href="#如何在-ubuntu-中修复-virtualbox-的-kernel-driver-not-installed-rc-1908-错误" aria-label="Permalink to “如何在 Ubuntu 中修复 VirtualBox 的 “Kernel driver not installed (rc=-1908)” 错误”">​</a></h1><p>我使用 Oracle VirtualBox 来测试各种 Linux 和 Unix 发行版。到目前为止，我已经在 VirtualBox 中测试了上百个虚拟机。今天，我在我的 Ubuntu 18.04 桌面上启动了 Ubuntu 18.04 服务器版虚拟机，我收到了以下错误。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Kernel driver not installed (rc=-1908)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The VirtualBox Linux kernel driver (vboxdrv) is either not loaded or there is a permission problem with /dev/vboxdrv. Please reinstall virtualbox-dkms package and load the kernel module by executing</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&#39;modprobe vboxdrv&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>as root.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>where: suplibOsInit what: 3 VERR_VM_DRIVER_NOT_INSTALLED (-1908) - The support driver is not installed. On linux, open returned ENOENT.</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/08/Kernel-driver-not-installed-virtualbox-ubuntu.png" alt=""></p><p><em>Ubuntu 中的 “Kernel driver not installed (rc=-1908)” 错误</em></p><p>我点击了 OK 关闭消息框，然后在后台看到了另一条消息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Failed to open a session for the virtual machine Ubuntu 18.04 LTS Server.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The virtual machine &#39;Ubuntu 18.04 LTS Server&#39; has terminated unexpectedly during startup with exit code 1 (0x1).</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Result Code:</span></span>
<span class="line"><span>NS_ERROR_FAILURE (0x80004005)</span></span>
<span class="line"><span>Component:</span></span>
<span class="line"><span>MachineWrap</span></span>
<span class="line"><span>Interface:</span></span>
<span class="line"><span>IMachine {85cd948e-a71f-4289-281e-0ca7ad48cd89}</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/08/The-virtual-machine-has-terminated-unexpectedly-during-startup-with-exit-code-1-0x1.png" alt=""></p><p><em>启动期间虚拟机意外终止，退出代码为 1（0x1）</em></p><p>我不知道该先做什么。我运行以下命令来检查是否有用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo modprobe vboxdrv</span></span></code></pre></div><p>我收到了这个错误：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>modprobe: FATAL: Module vboxdrv not found in directory /lib/modules/5.0.0-23-generic</span></span></code></pre></div><p>仔细阅读这两个错误消息后，我意识到我应该更新 Virtualbox 程序。</p><p>如果你在 Ubuntu 及其衍生版（如 Linux Mint）中遇到此错误，你只需使用以下命令重新安装或更新 <code>virtualbox-dkms</code> 包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install virtualbox-dkms</span></span></code></pre></div><p>或者，最好更新整个系统：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt upgrade</span></span></code></pre></div><p>错误消失了，我可以正常在 VirtualBox 中启动虚拟机了。</p><hr>`,20)),a("p",null,[n[11]||(n[11]=s("via: ",-1)),e(t,{href:"https://www.ostechnix.com/how-to-fix-kernel-driver-not-installed-rc-1908-virtualbox-error-in-ubuntu/"},{default:i(()=>[...n[10]||(n[10]=[s("https://www.ostechnix.com/how-to-fix-kernel-driver-not-installed-rc-1908-virtualbox-error-in-ubuntu/",-1)])]),_:1})]),a("p",null,[n[16]||(n[16]=s("作者：",-1)),e(t,{href:"https://www.ostechnix.com/author/sk/"},{default:i(()=>[...n[12]||(n[12]=[s("sk",-1)])]),_:1}),n[17]||(n[17]=s(" 选题：",-1)),e(t,{href:"https://github.com/lujun9972"},{default:i(()=>[...n[13]||(n[13]=[s("lujun9972",-1)])]),_:1}),n[18]||(n[18]=s(" 译者：",-1)),e(t,{href:"https://github.com/geekpi"},{default:i(()=>[...n[14]||(n[14]=[s("geekpi",-1)])]),_:1}),n[19]||(n[19]=s(" 校对：",-1)),e(t,{href:"https://github.com/wxy"},{default:i(()=>[...n[15]||(n[15]=[s("wxy",-1)])]),_:1})]),a("p",null,[n[22]||(n[22]=s("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...n[20]||(n[20]=[s("LCTT",-1)])]),_:1}),n[23]||(n[23]=s(" 原创编译，",-1)),e(t,{href:"https://linux.cn/"},{default:i(()=>[...n[21]||(n[21]=[s("Linux中国",-1)])]),_:1}),n[24]||(n[24]=s(" 荣誉推出",-1))])])}const w=l(d,[["render",h]]);export{m as __pageData,w as default};
